    perform(stop);cancelNoteTool(false);closeCommandPalette();PopupMenu::dismissAllActiveMenus();releaseKeys();project=emptyProject();selectedTrack=7;currentFile={};auto file=folder.getChildFile("tuning-A3.wav");check(tuningFixture(file),"create pitched stereo sampler fixture");auto hash=SHA256(file).toHexString();auto& source=project.tracks[7];source.instrument=Instrument::sample;source.samplePath=file.getFullPathName();source.send=0;source.sampleLoop=true;project.patterns[0].lanes[7]={{0,2,60,.8f}};undoStack.clear();redoStack.clear();dirty=false;publish();showPane(channelPane);auto context=samplerContext();check(context.has_value(),"loaded sampler exposes a range-bound tuning context");if(!context)return;auto before=JSON::toString(projectToJson(project));
    check(applySamplerTuning(*context,57,-23.5)&&undoStack.size()==1&&dirty,"manual sampler root and fine tune form one undoable edit");auto tuned=JSON::toString(projectToJson(project));perform(undoAction);check(JSON::toString(projectToJson(project))==before,"Undo restores previous sampler mapping and source");perform(redoAction);check(JSON::toString(projectToJson(project))==tuned,"Redo restores sampler root and precise cents");check(!applySamplerTuning(*context,60,0)&&JSON::toString(projectToJson(project))==tuned,"old tuning dialog rejects a stale project revision");context=samplerContext();auto count=undoStack.size();check(context&&applySamplerTuning(*context,57,-23.5)&&undoStack.size()==count,"applying existing tuning creates no redundant Undo");check(!applySamplerTuning(*context,128,0)&&!applySamplerTuning(*context,60,std::nan("")),"invalid manual sampler values cannot change the song");
