    startSamplerPitch(false);project.title="Changed during analysis";changed(false);if(samplePitchThread.joinable())samplePitchThread.join();finishSamplerPitch();check(!samplePitchValid&&project.tracks[7].sampleRoot==57,"changed project rejects a completed detection without applying it");
    startSamplerPitch(false);perform(samplerDetectCancel);if(samplePitchThread.joinable())samplePitchThread.join();finishSamplerPitch();check(!samplePitchValid&&!samplePitchBusy&&status.contains("cancelled"),"Cancel detection retains existing sampler tuning");
    startSamplerPitch(true);auto* blocker=new AlertWindow("Tuning result wait","Hold modal while analysis finishes.",MessageBoxIconType::NoIcon,this);blocker->addButton("Close",0);blocker->enterModalState(true,nullptr,true);if(samplePitchThread.joinable())samplePitchThread.join();finishSamplerPitch();check(samplePitchPresent&&Component::getCurrentlyModalComponent()==blocker,"finished pitch result waits for another modal to close");blocker->exitModalState(0);finishSamplerPitch();dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());check(dialog&&dialog->getTextEditor("cents")&&!samplePitchPresent,"deferred detection opens its tuning review after the launch dialog closes");if(dialog)dialog->exitModalState(0);
    context=samplerContext();auto stale=*context;file.appendData("x",1);check(!applySamplerTuning(stale,60,0),"changed source file rejects a stale tuning dialog");tuningFixture(file);context=samplerContext();selectedTrack=5;check(!applySamplerTuning(*context,60,0),"switching channels invalidates a pending tuning edit");selectedTrack=7;
    project.tracks[5].instrument=Instrument::sample;project.tracks[5].samplePath=file.getFullPathName();project.tracks[5].sampleRoot=45;project.tracks[5].sampleTune=12.25;project.tracks[5].sampleStart=.1;project.tracks[5].sampleEnd=.8;publish();browserLocal=false;browserFilter.clear();browserExpanded.fill(false);browserExpanded[3]=true;browserTreeScroll=0;setSize(1180,800);resetLayout();showPane(rackPane);Image image(Image::ARGB,getWidth(),getHeight(),true);Graphics graphics(image);paint(graphics);auto browser=std::find_if(browserAssets.begin(),browserAssets.end(),[](const BrowserAsset& entry){return entry.sampleRoot==45;});check(browser!=browserAssets.end()&&applyBrowserAsset(*browser,7)&&project.tracks[7].sampleRoot==45&&project.tracks[7].sampleTune==12.25,"Project sample assignment preserves source root cents and range");
