    prepareToPlay(1024,48000);activeInputs.store(0);activeOutputs.store(2);perform(stop);AudioBuffer<float> block(2,1024);getNextAudioBlock(AudioSourceChannelInfo(&block,0,1024));perform(play);getNextAudioBlock(AudioSourceChannelInfo(&block,0,1024));check(engine->playing.load()&&block.getMagnitude(0,0,1024)>.001f,"root-mapped sampler remains audible through the real callback");perform(stop);dirty=false;
