void Studio::runSamplerTuningTransportTick(){
    auto put=[&](const char* key,const var& value){transportResults.getDynamicObject()->setProperty(key,value);};
    if(transportTicks==2320){perform(stop);cancelNoteTool(false);closeCommandPalette();PopupMenu::dismissAllActiveMenus();auto file=transportReport.getSiblingFile("native-tuning-A3.wav");put("nativeSamplerFixture",tuningFixture(file));project=emptyProject();selectedTrack=7;currentFile={};auto& track=project.tracks[7];track.instrument=Instrument::sample;track.samplePath=file.getFullPathName();track.sampleLoop=true;track.send=0;project.patterns[0].lanes[7]={{0,4,60,.8f}};undoStack.clear();redoStack.clear();publish();perform(samplerTuningOpen);auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());put("nativeSamplerDialog",dialog&&dialog->getComboBoxComponent("root")->getNumItems()==128);if(dialog){dialog->getComboBoxComponent("root")->setSelectedItemIndex(57,dontSendNotification);dialog->getTextEditor("cents")->setText("-23.5");dialog->exitModalState(1);}}
    if(transportTicks==2330){put("nativeSamplerManual",project.tracks[7].sampleRoot==57&&project.tracks[7].sampleTune==-23.5&&undoStack.size()==1);perform(undoAction);bool undone=project.tracks[7].sampleRoot==60&&project.tracks[7].sampleTune==0;perform(redoAction);put("nativeSamplerUndo",undone&&project.tracks[7].sampleRoot==57);perform(samplerDetect);}
    if(transportTicks==2355){finishSamplerPitch();auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());put("nativeSamplerDetect",samplePitchValid&&!samplePitchBusy&&samplePitchResult.root==57&&std::abs(samplePitchResult.cents+23.5)<1);put("nativeSamplerReview",dialog&&dialog->getComboBoxComponent("root")->getSelectedItemIndex()==57);if(dialog){PNGImageFormat png;FileOutputStream output(transportReport.getSiblingFile("native-sampler-tuning.png"));if(output.openedOk())png.writeImageToStream(dialog->createComponentSnapshot(dialog->getLocalBounds()),output);dialog->exitModalState(1);}}
    if(transportTicks==2370){auto file=transportReport.getSiblingFile("native-tuned.pulse");Project saved;put("nativeSamplerSave",saveProject(project,file).wasOk()&&loadProject(file,saved).wasOk()&&saved.tracks[7].sampleRoot==57&&std::abs(saved.tracks[7].sampleTune+23.5)<1);if(auto context=samplerContext()){recording=true;put("nativeSamplerRecording",!applySamplerTuning(*context,60,0)&&!startSamplerPitch(false));recording=false;auto stale=*context;project.title="Tuning revised";changed(false);put("nativeSamplerStale",!applySamplerTuning(stale,60,0));}perform(play);transportFrames=engine->processedFrames.load();}
    if(transportTicks==2390){put("nativeSamplerAudio",engine->playing.load()&&engine->processedFrames.load()>transportFrames&&engine->observedPeak.load()>.001f);perform(stop);startSamplerPitch(false);perform(samplerDetectCancel);}
    if(transportTicks==2410){finishSamplerPitch();put("nativeSamplerCancel",!samplePitchBusy&&!samplePitchValid&&project.tracks[7].sampleRoot==57);perform(samplerTuningOpen);auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());if(dialog)dialog->exitModalState(3);}
    if(transportTicks==2420){put("nativeSamplerReset",project.tracks[7].sampleRoot==60&&project.tracks[7].sampleTune==0);perform(stop);}
}
